SELECT number AS "Цикл",started_at AT TIME ZONE 'Asia/Irkutsk' AS "Начало",ended_at AT TIME ZONE 'Asia/Irkutsk' AS "Завершение",CASE outcome WHEN 'active' THEN 'Активен' WHEN 'closed' THEN 'Закрыт' WHEN 'cancelled' THEN 'Отменён' ELSE 'Нет данных' END AS "Результат",u.name AS "Закрывший",d.name AS "Отдел",resolution AS "Описание результата",
 calendar_seconds/3600 AS "Срок, кал. ч",work_seconds/3600 AS "Срок, раб. ч",waiting_work_seconds/3600 AS "Ожидание, раб. ч",work_without_waiting_seconds/3600 AS "Без ожидания, раб. ч",first_response_work_seconds/60 AS "Первый ответ, раб. мин",r.name AS "Автор ответа",c.incomplete AS "Неполная история"
FROM analytics.cycles c LEFT JOIN analytics.employees u ON u.id=c.closed_by LEFT JOIN analytics.employees r ON r.id=c.first_response_by LEFT JOIN analytics.departments d ON d.code=c.department WHERE ticket_id={{ticket_id}} ORDER BY number
